mapper.select:
SELECT R.LEAVE_ID, R.USER_ID, U.USER_NM, R.LEAVE_TYPE, R.START_DE, R.END_DE, R.DAYS, R.REASON, R.STATUS, R.APPROVER_ID, A.USER_NM AS APPROVER_NM, R.APPROVED_DT, R.REJECT_REASON, R.REGIST_DT, R.UPDT_DT FROM LEAVE_REQUEST R LEFT JOIN APP_USER U ON U.USER_ID = R.USER_ID LEFT JOIN APP_USER A ON A.USER_ID = R.APPROVER_ID
AND R.START_DE LIKE #{leaveYear} || '%'
AND R.STATUS = #{status}
AND (R.USER_ID LIKE '%' || #{searchKeyword} || '%' OR U.USER_NM LIKE '%' || #{searchKeyword} || '%' OR R.REASON LIKE '%' || #{searchKeyword} || '%')
ORDER BY R.REGIST_DT DESC, R.LEAVE_ID DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT B.USER_ID, U.USER_NM, B.LEAVE_YEAR, B.TOTAL_DAYS, B.USED_DAYS, (B.TOTAL_DAYS - B.USED_DAYS - COALESCE(( SELECT SUM(R.DAYS) FROM LEAVE_REQUEST R WHERE R.USER_ID = B.USER_ID AND R.STATUS = 'REQUESTED' AND SUBSTRING(R.START_DE, 1, 4) = B.LEAVE_YEAR ), 0)) AS REMAIN_DAYS, B.UPDT_DT FROM LEAVE_BALANCE B JOIN APP_USER U ON U.USER_ID = B.USER_ID WHERE B.LEAVE_YEAR = #{leaveYear}
AND (B.USER_ID LIKE '%' || #{searchKeyword} || '%' OR U.USER_NM LIKE '%' || #{searchKeyword} || '%')
ORDER BY U.USER_NM, B.USER_ID LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT COUNT(*)
FROM LEAVE_REQUEST
WHERE USER_ID = #{userId}
	AND STATUS IN ('REQUESTED', 'APPROVED')
	AND START_DE <= #{endDe}
	AND END_DE >= #{startDe}

mapper.update:
UPDATE LEAVE_REQUEST
SET
	STATUS = 'CANCELLED',
	UPDT_DT = CURRENT_TIMESTAMP
WHERE LEAVE_ID = #{leaveId}
	AND USER_ID = #{userId}
	AND STATUS = #{status}

UPDATE LEAVE_BALANCE
SET
	USED_DAYS = CASE WHEN USED_DAYS - #{days} < 0 THEN 0 ELSE USED_DAYS - #{days} END,
	UPDT_DT = CURRENT_TIMESTAMP
WHERE USER_ID = #{userId}
	AND LEAVE_YEAR = #{leaveYear}

